import {plan} from './engine.mjs';
let loading,map,polylines=[];
const coord=p=>({lat:typeof p.lat==='function'?p.lat():p.lat,lng:typeof p.lng==='function'?p.lng():p.lng});
function distance(a,b){a=coord(a);b=coord(b);const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlng=(b.lng-a.lng)*r;return 6371*2*Math.asin(Math.sqrt(Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlng/2)**2));}
export async function connect(key){if(window.google?.maps?.importLibrary)return;if(!loading)loading=new Promise((resolve,reject)=>{const script=document.createElement('script');window.attoMapsReady=resolve;window.gm_authFailure=()=>reject(Error('Google rejected this key. Check API restrictions, billing and allowed website origins.'));script.src=`https://maps.googleapis.com/maps/api/js?key=${encodeURIComponent(key)}&v=weekly&loading=async&callback=attoMapsReady`;script.onerror=()=>reject(Error('Could not load Google Maps. Check your connection.'));document.head.append(script);setTimeout(()=>reject(Error('Google Maps took too long to load. Check your key and reload the page.')),20000);});return loading;}
async function compute(origin,destination,intermediates=[]){const {Route}=await google.maps.importLibrary('routes');const {routes}=await Route.computeRoutes({origin,destination,intermediates,travelMode:'DRIVING',routingPreference:'TRAFFIC_AWARE',fields:['path','distanceMeters','durationMillis','legs'],region:'tr'});if(!routes[0])throw Error('Google found no driving route. Check both addresses.');return routes[0];}
async function profileFor(raw){const {ElevationService}=await google.maps.importLibrary('elevation');const path=raw.path.filter((_,i)=>i===0||i===raw.path.length-1||i%Math.max(1,Math.ceil(raw.path.length/250))===0).map(coord);if(path.length<2)throw Error('The route is too short for an elevation profile.');const {results}=await new ElevationService().getElevationAlongPath({path,samples:256});if(results.length<2)throw Error('Elevation data unavailable. No reserve-safe route can be calculated.');return results.map((p,i)=>({km:i/(results.length-1)*raw.distanceMeters/1000,elevation:p.elevation}));}
export async function discover(s,status){status('Calculating road route and elevation…');const raw=await compute(s.origin,s.destination);if(raw.distanceMeters>1200000)throw Error('This first version supports routes up to 1,200 km. Split this journey into shorter trips.');const profile=await profileFor(raw),path=raw.path.map(coord),cumulative=[0];for(let i=1;i<path.length;i++)cumulative[i]=cumulative[i-1]+distance(path[i-1],path[i]);const scale=raw.distanceMeters/1000/cumulative.at(-1);const {Place}=await google.maps.importLibrary('places');const found=new Map();const count=Math.min(24,Math.max(2,Math.ceil(raw.distanceMeters/1000/45)));for(let i=0;i<=count;i++){status(`Finding compatible chargers · ${i+1}/${count+1} areas…`);const target=cumulative.at(-1)*i/count;const idx=cumulative.findIndex(k=>k>=target);const {places}=await Place.searchNearby({fields:['id','displayName','location','evChargeOptions'],locationRestriction:{center:path[idx],radius:25000},includedTypes:['electric_vehicle_charging_station'],maxResultCount:20});for(const p of places){const name=p.displayName||'';const network=/\bzes\b/i.test(name)?'ZES':/lumicle/i.test(name)?'Lumicle':/astor/i.test(name)?'Astor':/\bwat\b|wat mobilite/i.test(name)?'WAT':/trugo/i.test(name)?'Trugo':null;if(!network||!p.location)continue;const compatible=(p.evChargeOptions?.connectorAggregations||[]).filter(c=>c.type==='CCS_COMBO_2'||(!s.fastOnly&&c.type==='TYPE_2'));const power=Math.max(0,...compatible.map(c=>c.maxChargeRateKw||0));if(!power)continue;let nearest=0,off=Infinity;for(let n=0;n<path.length;n++){const d=distance(path[n],p.location);if(d<off){nearest=n;off=d;}}const km=cumulative[nearest]*scale;if(off>12||km<2||km>raw.distanceMeters/1000-2)continue;found.set(p.id,{id:p.id,name,network,km,power,detour:off,location:coord(p.location)});}}
return {source:'google',origin:s.origin,destination:s.destination,distance:raw.distanceMeters/1000,duration:raw.durationMillis/60000,profile,stations:[...found.values()],raw};}
// Re-route through chosen stations, including motorway access, then re-plan on those actual legs.
// Reject plans that cannot be validated; do not substitute a sample result.
export async function verify(route,s,excluded,status){const provisional=plan(route,s,excluded);status('Checking road access and reserve for the selected stops…');const raw=await compute(s.origin,s.destination,provisional.stops.map(x=>({location:x.location})));let offset=0;const profile=[],stations=[];for(let i=0;i<raw.legs.length;i++){const leg=raw.legs[i];const legProfile=await profileFor({path:leg.path,distanceMeters:leg.distanceMeters});profile.push(...legProfile.map(p=>({...p,km:p.km+offset})));offset+=leg.distanceMeters/1000;if(provisional.stops[i])stations.push({...provisional.stops[i],km:offset,detour:0});}const verified={...route,raw,profile,stations,distance:offset,duration:raw.durationMillis/60000};const result=plan(verified,s,[]);if(result.stops.length!==stations.length)throw Error('The road-access check changed this stop sequence. Try another priority or exclude a station and calculate again.');return {route:verified,result};}
export async function draw(route){const {Map}=await google.maps.importLibrary('maps');if(!map)map=new Map(document.querySelector('#googleMap'),{center:{lat:39.5,lng:28.8},zoom:7,disableDefaultUI:true,zoomControl:true});polylines.forEach(p=>p.setMap(null));polylines=route.raw.createPolylines({polylineOptions:{strokeColor:'#295d45',strokeWeight:5}});polylines.forEach(p=>p.setMap(map));const bounds=new google.maps.LatLngBounds();route.raw.path.forEach(p=>bounds.extend(coord(p)));map.fitBounds(bounds,45);}
